/* Подготовка запроса к Ollama API */
const inputData = $input.first().json;
const message = inputData.body?.message ?? inputData.message ?? inputData.query?.message ?? (typeof inputData.body === 'string' ? inputData.body : '');

const systemPrompt = 'You are a message classifier. Analyze the user message and return ONLY a valid JSON object (no markdown, no code fences) with exactly these fields:\n- category: one of "price", "consultation", "other"\n- summary: brief summary of the message in Russian\n- reply_draft: a polite draft reply in Russian\n\nClassification rules:\n- "price": the message asks about prices, cost, subscription fees, payment, tariffs\n- "consultation": the message asks for advice, consultation, help, technical questions, integration\n- "other": greetings, thanks, complaints, or anything else\n\nReturn JSON only.';

const requestBody = {
  model: 'glm-5.2:cloud',
  stream: false,
  format: 'json',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: String(message) }
  ]
};

return [{ json: { requestBody, originalMessage: String(message) } }];

/* Парсинг ответа LLM с обработкой markdown-обёрток */
const input = $input.first().json;
const rawContent = input.message?.content ?? input.content ?? '';
const originalMessage = $('Prepare LLM Request').first().json.originalMessage || '';

let text = String(rawContent).trim();

// Убираем markdown code-fences если модель их добавила
text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  // Fallback: извлекаем JSON-объект из текста
  const match = text.match(/\{[\s\S]*\}/);
  if (match) {
    try { parsed = JSON.parse(match[0]); } catch (e2) { parsed = {}; }
  }
}

// Нормализуем категорию
const validCategories = ['price', 'consultation', 'other'];
let category = String(parsed.category || '').toLowerCase().trim();
if (!validCategories.includes(category)) {
  category = 'other';
}

return [{
  json: {
    message_text: originalMessage,
    category: category,
    summary: String(parsed.summary || ''),
    reply_draft: String(parsed.reply_draft || parsed.reply || ''),
    date: new Date().toISOString(),
    status: 'processed'
  }
}];
